rows=[]
for line in open(src,encoding='utf-8',errors='ignore'):
    if '<frame ' not in line and '<section ' not in line:
        continue
    m=re.search(r'<(frame|section) id="([^"\n]+)" name="([^"\n]*)" x="([^"\n]*)" y="([^"\n]*)" width="([^"\n]*)" height="([^"\n]*)"', line)
    if not m:
        continue
    kind,id_,name,x,y,w,h=m.groups()
    indent=len(line)-len(line.lstrip(' '))
    try:
        x=float(x); y=float(y); w=float(w); h=float(h)
    except:
        continue
    if indent<=6 and (kind=='section' or (w>=1200 and h>=900)) and name.strip():
        if not re.fullmatch(r'Frame ?\d*', name.strip(), re.I):
            rows.append((x,y,indent,kind,id_,name.strip(),w,h))
rows.sort()
seen=set()
for x,y,indent,kind,id_,name,w,h in rows:
    key=(name.lower(), round(x/50), round(y/50))
    if key in seen:
        continue
    seen.add(key)
    print(f'{id_}\t{name}\t{kind}\tindent={indent}\tpos=({x:g},{y:g})\tsize=({w:g},{h:g})')
